-- =============================================================================
-- 545 — LE CAHIER D'EXERCICES DE 1RE (partie 33)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 545 --niveau 1re --fichiers ses.n1,ses.n2 --suffixe 33 > supabase/contenu/545_exercices_1re_33.sql
--
-- 69 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   ses.n1                  36 exercices · 12 chapitres
--   ses.n2                  33 exercices · 11 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('9d54ed6e-8234-52d8-8672-caa4a6dea667'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois façons de se rencontrer pour échanger","competence":"analyser-document","situation":"Zoé prépare un exposé : « Un marché, c’est forcément une place avec des étals. » Elle a relevé trois lieux d’échange très différents dans son quartier et sur Internet. À toi de vérifier son idée.","documents":[{"id":"lieux","type":"tableau","titre":"Trois lieux d’échange","source":"Situations imaginées pour l’exercice.","colonnes":["Lieu d’échange","Où se rencontrent offre et demande ?","Ce qui en sort"],"lignes":[["Marché du samedi","Sur la place du village","Le prix du kilo de pommes"],["Site de petites annonces","Sur Internet, sans lieu physique","Le prix d’un vélo d’occasion"],["Marché du travail","Offres d’emploi et candidatures","Un salaire et un nombre d’embauches"]],"enteteLignes":true}],"questions":[{"enonce":"Que conclure pour les trois lieux d’échange du tableau ?","aide":"Relis la deuxième colonne : y a-t-il, à chaque fois, des offreurs et des demandeurs qui se rencontrent ?","type":"choix","options":[{"id":"a","texte":"Seuls le marché du samedi et le site d’annonces sont des marchés"},{"id":"b","texte":"Ce sont trois marchés, mais seulement parce que l’État y fixe le prix"},{"id":"c","texte":"Ce sont trois marchés : à chaque fois, une offre et une demande se rencontrent"},{"id":"d","texte":"Seule la place du village est un marché : il faut un lieu où se rendre"}],"multiple":false},{"enonce":"Sur le site de petites annonces, qu’est-ce qui sort de la rencontre entre l’offre et la demande ? Touche la case.","aide":"Regarde la troisième colonne, sur la ligne du site d’annonces.","type":"zone","document":"lieux","multiple":false},{"enonce":"Pour que Zoé puisse vendre son vélo, il faut des règles. Associe chaque règle à ce qu’elle permet.","aide":"Une règle se rattache à une institution : la propriété, la monnaie, la justice, les normes.","type":"association","gauche":[{"id":"g0","texte":"Des droits de propriété définis"},{"id":"g1","texte":"Une monnaie acceptée par tous"},{"id":"g2","texte":"Des contrats exécutoires"},{"id":"g3","texte":"De l’information"}],"droite":[{"id":"d0","texte":"La justice les fait respecter"},{"id":"d1","texte":"On évite le troc"},{"id":"d2","texte":"On ne vend que ce qu’on possède"},{"id":"d3","texte":"Étiquetage, normes, garanties"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"Un marché est le lieu, **réel ou non**, de rencontre entre une offre et une demande. Les trois lignes en sont : le marché du travail comme le site d’annonces en font partie, **au même titre que la place du village**."},{"cle":{"type":"zone","ids":["r1c2"]},"explication":"De la rencontre entre l’offre et la demande sortent toujours **un prix et une quantité échangée** : ici, le prix d’un vélo d’occasion."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"Le marché est une **institution** : sans droits de propriété, monnaie, contrats garantis par la justice et information, l’échange n’est pas possible. **Sans État de droit, pas de marché.**"}]$ex$::jsonb),
  ('9d54ed6e-8234-52d8-8672-caa4a6dea667'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le prix de la baguette tradition","competence":"analyser-texte","situation":"Sofiane, boulanger, doit annoncer une hausse du prix de la baguette tradition après un été difficile. Son article de blog montre comment un prix agit sur des dizaines de personnes qu’il ne connaît pas.","documents":[{"id":"blog","type":"texte","genre":"article","titre":"Le blog de la boulangerie","source":"Texte écrit pour l’exercice.","blocs":["Cet été, la sécheresse a réduit la récolte de blé. Le prix de la baguette tradition passe donc de 1,20 € à 1,32 €.","Dès lundi, plusieurs clients ont renoncé à la tradition pour prendre la baguette ordinaire, moins chère.","À la coopérative, des agriculteurs ont décidé de semer davantage de blé à l’automne : la hausse du prix rend la culture plus rentable."]}],"questions":[{"enonce":"De combien, en %, le prix de la baguette tradition a-t-il augmenté ?","aide":"Taux de variation = (prix final − prix initial) ÷ prix initial. Ici : (1,32 − 1,20) ÷ 1,20.","type":"nombre","unite":"%"},{"enonce":"Touche le mot de l’article qui explique pourquoi le blé est devenu rare.","aide":"Cherche une cause climatique dans le premier paragraphe.","type":"zone","document":"blog","multiple":false},{"enonce":"Range chaque fait de l’article selon le rôle que joue le prix.","aide":"Informer = dire quelque chose ; inciter = pousser les producteurs à agir ; rationner = écarter des acheteurs.","type":"categories","categories":[{"id":"c0","texte":"Il informe"},{"id":"c1","texte":"Il incite"},{"id":"c2","texte":"Il rationne"}],"items":[{"id":"i0","texte":"Des agriculteurs sèment davantage de blé."},{"id":"i1","texte":"Les producteurs voient que produire devient plus rentable."},{"id":"i2","texte":"Des clients renoncent à la tradition à ce prix."},{"id":"i3","texte":"La hausse signale que le blé est devenu rare."}]},{"enonce":"Agriculteurs, meuniers et clients ajustent leurs décisions. Qui organise cet ajustement ?","aide":"Pense au ressort du marché : prix, ordre ou obligation sociale ?","type":"choix","options":[{"id":"a","texte":"Le prix, sans qu’aucun bureau central ne coordonne ces décisions"},{"id":"b","texte":"Un ordre donné par Sofiane à tous les clients"},{"id":"c","texte":"L’obligation sociale de s’entraider entre voisins"},{"id":"d","texte":"Un bureau central qui répartit le blé entre les boulangers"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 %","explication":"(1,32 − 1,20) ÷ 1,20 = 0,12 ÷ 1,20 = 0,10, soit une hausse de **10 %**."},{"cle":{"type":"zone","ids":["m3"]},"explication":"C’est la **sécheresse** qui a réduit la récolte : le prix monte parce que le produit est devenu rare. Le prix **informe**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c2","i3":"c0"}},"explication":"Une hausse **informe** (le produit est rare), **incite** les producteurs à en offrir davantage et **rationne** : elle écarte les acheteurs qui n’en veulent pas à ce prix."},{"cle":{"type":"choix","ids":["a"]},"explication":"Sur un marché, le prix **coordonne des millions de décisions individuelles sans bureau central**. L’ordre est le ressort de la hiérarchie, l’obligation sociale celui de la réciprocité."}]$ex$::jsonb),
  ('9d54ed6e-8234-52d8-8672-caa4a6dea667'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Vendre une console : plateforme ou bouche-à-oreille ?","competence":"raisonner","situation":"Hugo veut revendre sa console 80 €. Il hésite entre une plateforme d’annonces et le bouche-à-oreille. Il chiffre ce que lui coûte chaque solution, en temps et en argent, avant même d’encaisser.","documents":[{"id":"couts","type":"tableau","titre":"Les coûts d’une vente, en euros","source":"Chiffres imaginés pour l’exercice.","colonnes":["Poste","Annonce sur plateforme","Bouche-à-oreille"],"lignes":[["Chercher un acheteur (temps valorisé)",2,12],["Négocier et vérifier l’état de la console",3,8],["Exécuter la vente (paiement, remise)",3,5],["Commission de la plateforme",4,0]],"enteteLignes":true},{"id":"sms","type":"dialogue","modele":"sms","titre":"Les messages d’Hugo cette semaine","source":"Dialogues écrits pour l’exercice.","participants":[{"nom":"Hugo","emoji":"🧑","cote":"droite"},{"nom":"Voisin","emoji":"🧓","cote":"gauche"},{"nom":"Chef","emoji":"👔","cote":"gauche"}],"repliques":[{"qui":"Voisin","texte":"Je garde ton chat ce week-end, tu m’aideras à déménager la semaine prochaine ?"},{"qui":"Chef","texte":"Hugo, tu ranges le stock avant 18 h, c’est la consigne."},{"qui":"Hugo","texte":"Je vends ma console 80 €, premier arrivé, premier servi."}]}],"questions":[{"enonce":"Quel est le coût total des coûts de transaction du bouche-à-oreille, en euros ?","aide":"Additionne les quatre lignes de la dernière colonne.","type":"nombre","unite":"€"},{"enonce":"Combien d’euros de coûts la plateforme fait-elle économiser à Hugo, commission comprise ?","aide":"Calcule d’abord le total de la plateforme (2 + 3 + 3 + 4), puis compare.","type":"nombre","unite":"€"},{"enonce":"Remets dans l’ordre les étapes d’un échange que les coûts de transaction rendent coûteux.","aide":"On commence par chercher qui vend quoi et finit par s’assurer que l’accord est tenu.","type":"ordre","items":[{"id":"a","texte":"Le faire respecter"},{"id":"b","texte":"Négocier"},{"id":"c","texte":"Rédiger le contrat"},{"id":"d","texte":"Chercher l’information"}]},{"enonce":"Associe chaque message à son mode de coordination.","aide":"Cherche le ressort de chaque phrase : un prix, un ordre, un service qu’on rend.","type":"association","gauche":[{"id":"g0","texte":"Je garde ton chat, tu m’aideras à déménager"},{"id":"g1","texte":"Tu ranges le stock avant 18 h"},{"id":"g2","texte":"Premier arrivé, premier servi, 80 €"}],"droite":[{"id":"d0","texte":"Hiérarchie : l’ordre"},{"id":"d1","texte":"Marché : le prix"},{"id":"d2","texte":"Réciprocité : l’obligation sociale"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 €","explication":"12 + 8 + 5 + 0 = **25 €**."},{"cle":{"type":"nombre","valeur":13,"tolerance":0},"affichage":"13 €","explication":"Plateforme : 2 + 3 + 3 + 4 = 12 €. Bouche-à-oreille : 25 €. Écart : 25 − 12 = **13 €**. Les plateformes vivent de cette **réduction des coûts de transaction**."},{"cle":{"type":"ordre","ids":["d","b","c","a"]},"explication":"On **cherche l’information**, on **négocie**, on **rédige le contrat**, puis on **le fait respecter** : échanger n’est jamais gratuit."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Le **marché** s’appuie sur le prix, la **hiérarchie** sur l’ordre, la **réciprocité** sur l’obligation sociale. Une économie réelle mêle les trois."}]$ex$::jsonb),
  ('d2a9018d-a9dd-53bb-b458-242bfe7f4808'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le marché des fraises de Quimper","competence":"lire-graphique","situation":"Chaque samedi, des maraîchers vendent leurs fraises sur le marché de Quimper. Les courbes ci-dessous résument ce que les acheteurs veulent et ce que les producteurs proposent selon le prix.","documents":[{"id":"md","type":"graphique","forme":"courbe","titre":"Offre et demande de fraises","source":"Données imaginées pour l’exercice.","categories":["0","100","200","300","400","500"],"series":[{"nom":"Demande","valeurs":[9,8,7,6,5,4],"teinte":"corail"},{"nom":"Offre","valeurs":[3,4,5,6,7,8],"teinte":"bleu"}],"axeY":{"titre":"Prix","unite":"en € le kilo","min":0,"max":10,"pas":1},"axeX":{"titre":"Quantité (kg)"}}],"questions":[{"enonce":"Touche la quantité pour laquelle les deux courbes se croisent.","aide":"Cherche l’abscisse où l’offre et la demande donnent le même prix.","type":"zone","document":"md","multiple":false},{"enonce":"Quel est le prix d’équilibre, en euros le kilo ?","aide":"Lis l’ordonnée du point d’intersection.","type":"nombre","unite":"€/kg"},{"enonce":"Si le prix était de 7 € le kilo, de combien de kilos l’offre dépasserait-elle la demande ?","aide":"À 7 €, repère la quantité sur chaque courbe : la demande à 7 €, l’offre à 7 €.","type":"nombre","unite":"kg"},{"enonce":"Dans ce cas (prix de 7 €), que va-t-il se passer ?","aide":"Quand l’offre dépasse la demande, qu’arrive-t-il aux invendus ?","type":"choix","options":[{"id":"a","texte":"La pénurie fait monter les enchères"},{"id":"b","texte":"Les invendus font baisser le prix vers l’équilibre"},{"id":"c","texte":"Le prix reste à 7 € car le marché est équilibré"},{"id":"d","texte":"Les producteurs réduisent l’offre sans changer le prix"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"Les courbes se croisent à **300 kg** : c’est la quantité d’équilibre."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 €/kg","explication":"À 300 kg, la demande et l’offre valent toutes deux 6 : le prix d’équilibre est de **6 € le kilo**."},{"cle":{"type":"nombre","valeur":200,"tolerance":0},"affichage":"200 kg","explication":"À 7 €, la demande est de 200 kg et l’offre de 400 kg : l’offre dépasse la demande de **200 kg**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Si le prix est trop élevé, l’offre dépasse la demande : la **mévente fait baisser le prix** jusqu’à l’équilibre."}]$ex$::jsonb),
  ('d2a9018d-a9dd-53bb-b458-242bfe7f4808'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Quand les salaires augmentent, les fraises aussi","competence":"modeliser","situation":"La région vient de voir augmenter les salaires : les ménages ont plus de revenu à dépenser. Les maraîchers de Quimper n’ont rien changé à leur production. Que devient le marché des fraises ?","documents":[{"id":"md2","type":"graphique","forme":"courbe","titre":"Le marché avant et après la hausse des revenus","source":"Données imaginées pour l’exercice.","categories":["0","100","200","300","400","500"],"series":[{"nom":"Demande avant","valeurs":[9,8,7,6,5,4],"teinte":"gris"},{"nom":"Demande après","valeurs":[11,10,9,8,7,6],"teinte":"corail"},{"nom":"Offre","valeurs":[3,4,5,6,7,8],"teinte":"bleu"}],"axeY":{"titre":"Prix","unite":"en € le kilo","min":0,"max":12,"pas":2},"axeX":{"titre":"Quantité (kg)"}}],"questions":[{"enonce":"Qu’est-ce qui explique que la courbe de demande se soit décalée ?","aide":"Une variation du prix déplace le long de la courbe ; tout autre facteur déplace la courbe entière.","type":"choix","options":[{"id":"a","texte":"Les producteurs sont devenus preneurs de prix"},{"id":"b","texte":"Le coût de production a baissé : la courbe d’offre s’est décalée"},{"id":"c","texte":"Le revenu a augmenté : c’est la courbe entière qui se décale vers la droite"},{"id":"d","texte":"Le prix a augmenté : on s’est déplacé le long de la courbe de demande"}],"multiple":false},{"enonce":"Touche la nouvelle quantité d’équilibre, après la hausse des revenus.","aide":"Cherche où la nouvelle demande croise l’offre, qui n’a pas bougé.","type":"zone","document":"md2","multiple":false},{"enonce":"Quel est le nouveau prix d’équilibre, en euros le kilo ?","aide":"Lis le prix à l’intersection de la nouvelle demande et de l’offre.","type":"nombre","unite":"€/kg"},{"enonce":"De combien, en %, le prix d’équilibre a-t-il augmenté ? Arrondis au dixième.","aide":"Taux de variation = (7 − 6) ÷ 6.","type":"nombre","unite":"%"},{"enonce":"Pour l’offre, que s’est-il passé entre les deux équilibres ?","aide":"Aucun facteur autre que le prix n’a changé du côté des producteurs.","type":"choix","options":[{"id":"a","texte":"On s’est déplacé le long de la courbe d’offre, qui est restée en place"},{"id":"b","texte":"La courbe d’offre entière s’est décalée vers la droite du graphique"},{"id":"c","texte":"La courbe d’offre est devenue décroissante avec la hausse du prix"},{"id":"d","texte":"La courbe d’offre entière s’est décalée vers la gauche du graphique"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"Un changement de **revenu** n’est pas une variation du prix du bien : il **décale la courbe de demande entière vers la droite**."},{"cle":{"type":"zone","ids":["k4"]},"explication":"La nouvelle demande croise l’offre à **400 kg** : c’est la nouvelle quantité d’équilibre."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7 €/kg","explication":"À 400 kg, la nouvelle demande et l’offre valent 7 : le nouveau prix d’équilibre est de **7 € le kilo**, plus élevé qu’avant."},{"cle":{"type":"nombre","valeur":16.7,"tolerance":0.1},"affichage":"16,7 %","explication":"(7 − 6) ÷ 6 ≈ 0,167, soit environ **+16,7 %**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Seul le prix a changé pour les producteurs : ils produisent plus (de 300 à 400 kg) **en se déplaçant le long de la courbe d’offre**."}]$ex$::jsonb),
  ('d2a9018d-a9dd-53bb-b458-242bfe7f4808'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Qui gagne à l’échange sur le marché aux gaufres ?","competence":"raisonner","situation":"À la fête de quartier, cinq gaufriers peuvent produire une gaufre à des coûts différents, et cinq gourmands sont prêts à payer des sommes variables. Le prix s’est établi à 6 €. Qui gagne quoi à l’échange ?","documents":[{"id":"ach","type":"tableau","titre":"Les acheteurs","source":"Chiffres imaginés pour l’exercice.","colonnes":["Acheteur","Prix maximum accepté (€)"],"lignes":[["A",10],["B",9],["C",8],["D",6],["E",4]],"enteteLignes":true},{"id":"ven","type":"tableau","titre":"Les gaufriers","source":"Chiffres imaginés pour l’exercice.","colonnes":["Gaufrier","Prix minimum accepté (€)"],"lignes":[["P1",2],["P2",3],["P3",5],["P4",6],["P5",8]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’acheteur qui renonce à acheter au prix de 6 €.","aide":"Il n’achète que si le prix ne dépasse pas ce qu’il accepte de payer.","type":"zone","document":"ach","multiple":false},{"enonce":"À 6 €, quatre acheteurs veulent acheter et quatre gaufriers veulent vendre. Que conclure ?","aide":"Compare le nombre d’acheteurs au nombre de vendeurs à 6 €.","type":"choix","options":[{"id":"a","texte":"La demande dépasse l’offre : le prix va monter"},{"id":"b","texte":"Le prix doit être fixé par un bureau central"},{"id":"c","texte":"L’offre égale la demande : 6 € est le prix d’équilibre"},{"id":"d","texte":"L’offre dépasse la demande : le prix va baisser"}],"multiple":false},{"enonce":"Quel est le surplus total des consommateurs (acheteurs A, B, C et D) au prix de 6 € ?","aide":"Pour chacun : ce qu’il était prêt à payer moins ce qu’il paie.","type":"nombre","unite":"€"},{"enonce":"Quel est le surplus total des producteurs (P1, P2, P3 et P4) au prix de 6 € ?","aide":"Pour chacun : le prix reçu moins le prix minimum qu’il acceptait.","type":"nombre","unite":"€"},{"enonce":"Quel est le gain total à l’échange ?","aide":"Le gain à l’échange est la somme des deux surplus.","type":"nombre","unite":"€"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r4c0"]},"explication":"L’acheteur **E** n’accepte pas plus de 4 € : il renonce à 6 €. Les quatre autres achètent."},{"cle":{"type":"choix","ids":["c"]},"explication":"Quantité offerte = quantité demandée = 4 : **6 € est bien le prix d’équilibre**."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9 €","explication":"(10 − 6) + (9 − 6) + (8 − 6) + (6 − 6) = 4 + 3 + 2 + 0 = **9 €**."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 €","explication":"(6 − 2) + (6 − 3) + (6 − 5) + (6 − 6) = 4 + 3 + 1 + 0 = **8 €**."},{"cle":{"type":"nombre","valeur":17,"tolerance":0},"affichage":"17 €","explication":"9 + 8 = **17 €** : c’est la somme du surplus du consommateur et du surplus du producteur."}]$ex$::jsonb),
  ('fe83dd47-a39c-5976-8aa3-0a598ff797a3'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Combien d’offreurs ? Quatre marchés à classer","competence":"lire-tableau","situation":"Dans une ville moyenne, Inès compare quatre marchés pour son exposé : à chaque fois, le nombre de vendeurs et le type de produit sont différents. Elle doit retrouver la structure de marché de chacun.","documents":[{"id":"marches","type":"tableau","titre":"Quatre marchés d’une ville","source":"Situations imaginées pour l’exercice.","colonnes":["Marché","Nombre d’offreurs","Produits"],"lignes":[["Un médicament sous brevet","Un seul","Un traitement unique"],["La distribution d’eau","Un seul (réseau unique)","Eau du robinet"],["Les grandes surfaces","Trois enseignes","Très semblables"],["Les restaurants du centre-ville","Plus de quatre-vingts","Cartes toutes différentes"]],"enteteLignes":true}],"questions":[{"enonce":"Range chaque marché dans sa structure.","aide":"Un seul offreur, quelques-uns ou beaucoup avec des produits différents ?","type":"categories","categories":[{"id":"c0","texte":"Monopole"},{"id":"c1","texte":"Oligopole"},{"id":"c2","texte":"Concurrence monopolistique"}],"items":[{"id":"i0","texte":"Un médicament sous brevet"},{"id":"i1","texte":"Les grandes surfaces"},{"id":"i2","texte":"Les restaurants du centre-ville"},{"id":"i3","texte":"La distribution d’eau"}]},{"enonce":"Touche le marché où chaque offreur détient « un petit monopole sur sa variété ».","aide":"Il y a beaucoup d’offreurs, et chacun a son produit à lui.","type":"zone","document":"marches","multiple":false},{"enonce":"Dans un monopole, le producteur est…","aide":"Sans concurrent, qui décide du prix ?","type":"choix","options":[{"id":"a","texte":"un preneur de prix : il subit le prix du marché"},{"id":"b","texte":"un intermédiaire sans pouvoir sur le prix"},{"id":"c","texte":"un offreur parmi une multitude, sans influence"},{"id":"d","texte":"un faiseur de prix : il dispose d’un pouvoir de marché"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c2","i3":"c0"}},"explication":"**Monopole** : un seul offreur. **Oligopole** : quelques offreurs. **Concurrence monopolistique** : beaucoup d’offreurs de produits différenciés."},{"cle":{"type":"zone","ids":["r3c0"]},"explication":"Les **restaurants** : beaucoup d’offreurs, chacun avec une carte différente. C’est la concurrence monopolistique."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le monopole est un **faiseur de prix** (*price maker*) : il peut fixer son prix au-dessus du coût marginal."}]$ex$::jsonb),
  ('fe83dd47-a39c-5976-8aa3-0a598ff797a3'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"La fin d’un brevet : ce que le prix raconte","competence":"lire-tableau","situation":"Un laboratoire fabriquait un sirop contre la toux protégé par un brevet. Le brevet vient de tomber : d’autres laboratoires produisent désormais le même sirop. Le tableau compare les deux situations.","documents":[{"id":"sirop","type":"tableau","titre":"Le sirop avant et après la fin du brevet","source":"Chiffres imaginés pour l’exercice. Le coût marginal est le coût de fabrication d’une boîte de plus.","colonnes":["","Sous brevet (monopole)","Après le brevet (concurrence)"],"lignes":[["Prix de vente (€ la boîte)",8,5],["Boîtes vendues par mois",600,1000],["Coût marginal (€ la boîte)",5,5]],"enteteLignes":true}],"questions":[{"enonce":"Touche le prix le plus élevé du tableau.","aide":"Compare les deux cases de la première ligne.","type":"zone","document":"sirop","multiple":false},{"enonce":"De combien, en %, le prix baisse-t-il après la fin du brevet ?","aide":"Taux de variation = (5 − 8) ÷ 8. Donne la valeur absolue de la baisse.","type":"nombre","unite":"%"},{"enonce":"Quel est le profit mensuel du laboratoire sous brevet, en euros ? (profit = (prix − coût marginal) × quantité)","aide":"Calcule d’abord le gain par boîte (8 − 5), puis multiplie par les boîtes vendues.","type":"nombre","unite":"€"},{"enonce":"Quel est le profit après la fin du brevet, avec la même formule ?","aide":"Compare le prix et le coût marginal dans la dernière colonne.","type":"nombre","unite":"€"},{"enonce":"Que retenir du monopole par rapport à la concurrence ?","aide":"Compare les deux colonnes ligne par ligne.","type":"choix","options":[{"id":"a","texte":"Un prix plus faible et une quantité plus forte"},{"id":"b","texte":"Un prix plus élevé et une quantité plus faible"},{"id":"c","texte":"Un prix plus élevé et une quantité plus forte"},{"id":"d","texte":"Un prix et une quantité identiques"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"Sous brevet, le prix est de **8 €** : le monopole fixe un prix supérieur au coût marginal."},{"cle":{"type":"nombre","valeur":37.5,"tolerance":0},"affichage":"37,5 %","explication":"(5 − 8) ÷ 8 = −0,375 : le prix baisse de **37,5 %**."},{"cle":{"type":"nombre","valeur":1800,"tolerance":0},"affichage":"1800 €","explication":"(8 − 5) × 600 = **1 800 €** par mois."},{"cle":{"type":"nombre","valeur":0,"tolerance":0},"affichage":"0 €","explication":"(5 − 5) × 1 000 = **0 €** : en concurrence, le prix se rapproche du coût marginal."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le monopole vend **plus cher et moins** (8 € pour 600 boîtes, contre 5 € pour 1 000) : une partie du surplus du consommateur lui est transférée."}]$ex$::jsonb),
  ('fe83dd47-a39c-5976-8aa3-0a598ff797a3'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les deux stations-service de Bayeux","competence":"raisonner","situation":"À Bayeux, deux stations-service se partagent la clientèle. Chaque directeur choisit chaque mois entre garder son prix ou le baisser, sans savoir ce que fera l’autre. Le tableau donne les bénéfices mensuels de chaque station.","documents":[{"id":"gains","type":"tableau","titre":"Bénéfices mensuels (milliers d’euros) : station A | station B","source":"Chiffres imaginés pour l’exercice.","colonnes":["","B garde son prix","B baisse son prix"],"lignes":[["A garde son prix","50 | 50","20 | 80"],["A baisse son prix","80 | 20","30 | 30"]],"enteteLignes":true},{"id":"presse","type":"texte","genre":"article","titre":"Un rendez-vous discret","source":"Article imaginé pour l’exercice.","blocs":["Les directeurs des deux stations se sont rencontrés en secret : « On garde le prix à 1,80 € tous les deux. » L’autorité de la concurrence a ouvert une enquête."]}],"questions":[{"enonce":"Touche la case qui correspond à une guerre des prix.","aide":"Dans cette case, les deux stations baissent leur prix.","type":"zone","document":"gains","multiple":false},{"enonce":"Si B garde son prix et que A le baisse, quel bénéfice A réalise-t-il, en milliers d’euros ?","aide":"Ligne « A baisse son prix », colonne « B garde son prix » : lis le premier nombre.","type":"nombre","unite":"k€"},{"enonce":"Si B baisse son prix, quel est le meilleur choix pour A ?","aide":"Compare, dans la colonne « B baisse son prix », les deux premiers nombres de A.","type":"choix","options":[{"id":"a","texte":"Garder son prix : 20 vaut mieux que 30"},{"id":"b","texte":"Garder son prix : 50 est atteint"},{"id":"c","texte":"Cela ne change rien pour A"},{"id":"d","texte":"Baisser aussi son prix : 30 vaut mieux que 20"}],"multiple":false},{"enonce":"Complète la conclusion.","aide":"Reprends l’issue de la guerre des prix et pense au consommateur.","type":"trous","segments":["Chaque station a intérêt à ",0," son prix : elles finissent à ",1," chacune, mais le consommateur y ",2,"."],"banque":["baisser","30","garder","perd","50","gagne"]},{"enonce":"Que montre l’article ? Comment qualifier le rendez-vous des directeurs ?","aide":"Les deux concurrents s’accordent sur un prix commun : quelle surveillance de la politique de la concurrence est visée ?","type":"choix","options":[{"id":"a","texte":"Une entente interdite, qui reconstitue un monopole"},{"id":"b","texte":"Un abus de position dominante d’une seule station"},{"id":"c","texte":"Une différenciation des produits par la publicité"},{"id":"d","texte":"Une concentration autorisée entre deux entreprises"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Quand **A et B baissent** leur prix, c’est la guerre des prix : 30 | 30."},{"cle":{"type":"nombre","valeur":80,"tolerance":0},"affichage":"80 k€","explication":"A gagne **80** : il prend des clients à B. C’est l’**interdépendance stratégique** : le résultat de chacun dépend du choix de l’autre."},{"cle":{"type":"choix","ids":["d"]},"explication":"Dans cette colonne, A obtient 20 s’il garde son prix et **30 s’il le baisse**. Chacun a intérêt à baisser, et les deux finissent à 30 au lieu de 50."},{"cle":{"type":"trous","trous":[["baisser"],["30"],["gagne"]]},"affichage":"baisser · 30 · gagne","explication":"Les deux stations **baissent** leur prix et finissent à **30**, moins que les 50 d’une entente. Pour le consommateur, la guerre des prix est **bénéfique** : il **gagne**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Un accord entre concurrents sur les prix est une **entente** (cartel) : elle est **interdite** car elle reconstitue un monopole, même si elle est discrète."}]$ex$::jsonb),
  ('7118e8be-6cb2-53c4-8e49-9984b72df615'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"L’usine de papier et la rivière","competence":"analyser-texte","situation":"L’usine de papier de Valmont a doublé sa production. Les habitants du village voisin se plaignent : la rivière n’est plus ce qu’elle était. Un journaliste local résume la situation.","documents":[{"id":"usine","type":"texte","genre":"article","titre":"Valmont : la rivière en colère","source":"Article écrit pour l’exercice.","blocs":["Depuis deux ans, l’usine de papier rejette ses eaux chargées dans la rivière. Les pêcheurs du village voisin ne ramènent presque plus rien.","L’usine vend son papier à un prix très bas : le coût de la pollution n’apparaît nulle part dans ses comptes. Les riverains, eux, n’ont reçu aucune compensation."]}],"questions":[{"enonce":"Touche le mot qui désigne ceux qui subissent la pollution sans compensation.","aide":"Qui ne ramène presque plus rien de la rivière ?","type":"zone","document":"usine","multiple":false},{"enonce":"De quel type d’externalité s’agit-il ?","aide":"Les riverains y gagnent-ils ou y perdent-ils ?","type":"choix","options":[{"id":"a","texte":"Une asymétrie d’information entre l’usine et les pêcheurs"},{"id":"b","texte":"Une externalité positive : un tiers profite d’un bienfait sans payer"},{"id":"c","texte":"Une externalité négative : un tiers subit un dommage sans compensation"},{"id":"d","texte":"Un bien collectif : la rivière est non rivale"}],"multiple":false},{"enonce":"Associe chaque remède à son principe.","aide":"Relie chaque outil à son idée directrice.","type":"association","gauche":[{"id":"g0","texte":"La taxe"},{"id":"g1","texte":"La subvention"},{"id":"g2","texte":"La réglementation"},{"id":"g3","texte":"Le marché de droits à polluer"}],"droite":[{"id":"d0","texte":"Encourager l’externalité positive"},{"id":"d1","texte":"Interdire ou imposer"},{"id":"d2","texte":"Des quotas échangeables"},{"id":"d3","texte":"Le pollueur-payeur"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"Les **pêcheurs** supportent un coût que personne ne leur rembourse : c’est une externalité."},{"cle":{"type":"choix","ids":["c"]},"explication":"La pollution est une **externalité négative** : un effet dommageable subi par un tiers sans compensation. Le prix est trop bas, la quantité produite trop élevée."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Taxe = **pollueur-payeur** ; subvention = on encourage ce qui bénéficie aux autres ; réglementation = on **interdit ou impose** ; droits à polluer = **quotas échangeables**."}]$ex$::jsonb),
  ('7118e8be-6cb2-53c4-8e49-9984b72df615'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le lampadaire de la rue des Lilas","competence":"lire-tableau","situation":"Les vingt habitants de la rue des Lilas veulent un lampadaire. Mais pourquoi payer si les autres paient ? Un tableau de biens et la cagnotte de la rue permettent de comprendre pourquoi le marché ne produit pas ce genre de bien.","documents":[{"id":"biens","type":"tableau","titre":"Rivalité et exclusion","source":"Caractéristiques simplifiées pour l’exercice.","colonnes":["Bien","Ma consommation empêche celle des autres ?","On peut en exclure quelqu’un ?"],"lignes":[["Un phare","Non","Non"],["Une tablette de chocolat","Oui","Oui"],["L’éclairage public","Non","Non"],["Une place de cinéma","Oui","Oui"]],"enteteLignes":true},{"id":"cagnotte","type":"tableau","titre":"La cagnotte de la rue","source":"Chiffres imaginés pour l’exercice.","colonnes":["Poste","Valeur"],"lignes":[["Coût du lampadaire (€)",600],["Nombre d’habitants",20],["Part demandée à chacun (€)",30],["Habitants qui ont payé",12]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux biens collectifs du tableau.","aide":"Un bien collectif est à la fois non rival et non excluable : cherche deux « Non ».","type":"zone","document":"biens","multiple":true},{"enonce":"Combien d’euros ont été collectés ?","aide":"Multiplie le nombre d’habitants qui ont payé par la part de chacun.","type":"nombre","unite":"€"},{"enonce":"Combien manque-t-il pour payer le lampadaire ?","aide":"Compare le coût total à la somme collectée.","type":"nombre","unite":"€"},{"enonce":"Comment s’appelle l’attitude des huit habitants qui profiteront du lampadaire sans payer ?","aide":"Ils profitent d’un bien collectif sans contribuer à son financement.","type":"choix","options":[{"id":"a","texte":"L’aléa moral des assurés"},{"id":"b","texte":"La sélection adverse du marché"},{"id":"c","texte":"Le passager clandestin"},{"id":"d","texte":"Le principe pollueur-payeur"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0","r2c0"]},"explication":"Le **phare** et l’**éclairage public** sont non rivaux et non excluables : ce sont des biens collectifs."},{"cle":{"type":"nombre","valeur":360,"tolerance":0},"affichage":"360 €","explication":"12 × 30 = **360 €**."},{"cle":{"type":"nombre","valeur":240,"tolerance":0},"affichage":"240 €","explication":"600 − 360 = **240 €** : huit habitants ont préféré attendre que les autres paient."},{"cle":{"type":"choix","ids":["c"]},"explication":"Comme personne ne peut être exclu, chacun a intérêt à attendre que les autres paient : c’est le **passager clandestin**. C’est pourquoi la puissance publique, financée par l’impôt, produit ces biens."}]$ex$::jsonb),
  ('7118e8be-6cb2-53c4-8e49-9984b72df615'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le marché des voitures d’occasion","competence":"raisonner","situation":"Dans une grande ville, des particuliers vendent des voitures d’occasion. Les vendeurs connaissent l’état de leur voiture ; les acheteurs, non. Cette asymétrie d’information finit par tuer le marché des bonnes voitures.","documents":[{"id":"voitures","type":"tableau","titre":"Les deux sortes de voitures","source":"Chiffres imaginés pour l’exercice.","colonnes":["Voiture","Part des voitures en vente","Valeur pour l’acheteur (€)","Prix minimum du vendeur (€)"],"lignes":[["Bonne voiture","50 %",10000,8000],["Mauvaise voiture (« lemon »)","50 %",4000,3000]],"enteteLignes":true},{"id":"dial","type":"dialogue","modele":"sms","titre":"À la vente","source":"Dialogue écrit pour l’exercice.","participants":[{"nom":"Acheteur","emoji":"🧑","cote":"gauche"},{"nom":"Vendeur","emoji":"🧔","cote":"droite"}],"repliques":[{"qui":"Acheteur","texte":"Je ne vois pas l’état réel de la voiture. Je vous propose le prix moyen du marché."},{"qui":"Vendeur","texte":"À ce prix-là, je la garde : la mienne est en parfait état."}]}],"questions":[{"enonce":"L’acheteur ne distingue pas les voitures. Quel prix moyen propose-t-il, en euros ? (moitié de bonnes, moitié de mauvaises)","aide":"Moyenne des deux valeurs pour l’acheteur, chacune comptant pour moitié.","type":"nombre","unite":"€"},{"enonce":"Touche les vendeurs qui refusent de vendre à ce prix moyen.","aide":"Compare 7 000 € au prix minimum de chaque vendeur.","type":"zone","document":"voitures","multiple":false},{"enonce":"Remets dans l’ordre la spirale décrite par Akerlof.","aide":"L’asymétrie d’information vient en premier, la disparition des bonnes voitures en dernier.","type":"ordre","items":[{"id":"a","texte":"Les propriétaires de bonnes voitures se retirent du marché"},{"id":"b","texte":"Il n’offre qu’un prix moyen"},{"id":"c","texte":"L’acheteur ne distingue pas les bonnes des mauvaises voitures"},{"id":"d","texte":"Il ne reste que des mauvaises voitures"}]},{"enonce":"Trie ces situations selon le moment où survient l’asymétrie d’information.","aide":"Demande-toi si l’information cachée concerne le moment de la signature ou ce qui se passe ensuite.","type":"categories","categories":[{"id":"c0","texte":"Avant le contrat (sélection adverse)"},{"id":"c1","texte":"Après le contrat (aléa moral)"}],"items":[{"id":"i0","texte":"Le vendeur cache l’état réel de sa voiture"},{"id":"i1","texte":"Un candidat à l’assurance cache ses antécédents"},{"id":"i2","texte":"Un assuré tous risques ne verrouille plus son vélo"},{"id":"i3","texte":"Un assuré sans franchise devient moins prudent"}]},{"enonce":"Quelle mesure réduit l’écart d’information entre vendeur et acheteur ?","aide":"Le remède consiste à rendre l’état de la voiture visible pour l’acheteur.","type":"choix","options":[{"id":"a","texte":"Une interdiction d’afficher le prix de vente"},{"id":"b","texte":"Un prix moyen fixé par l’acheteur"},{"id":"c","texte":"Un contrôle technique obligatoire avant la vente"},{"id":"d","texte":"Une taxe sur les bonnes voitures"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":7000,"tolerance":0},"affichage":"7000 €","explication":"0,5 × 10 000 + 0,5 × 4 000 = **7 000 €**."},{"cle":{"type":"zone","ids":["r0c3"]},"explication":"Le vendeur de bonne voiture veut au moins 8 000 € : il **se retire**. Le vendeur de « lemon » (3 000 €) accepte volontiers 7 000 €."},{"cle":{"type":"ordre","ids":["c","b","a","d"]},"explication":"L’asymétrie conduit à un prix moyen, les bons vendeurs se retirent et il ne reste que des **lemons** : c’est la **sélection adverse**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"**Avant** la signature : on cache une information (sélection adverse). **Après** : l’assuré change de comportement (**aléa moral**)."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **contrôle technique**, les garanties, les labels et les certifications **réduisent l’écart d’information** : c’est le principe commun des remèdes."}]$ex$::jsonb),
  ('5cb90b22-e562-5dd6-a744-4d7ae5f423a0'::uuid, 1, 1, 5, 20, 4,
