   $ex${"titre":"Action ou obligation : le choix de la Brasserie du Cap","competence":"analyser-document","situation":"La Brasserie du Cap veut financer une nouvelle usine. Son fondateur compare deux titres qu’il pourrait émettre. Il se demande surtout ce que chacun lui coûte, et à qui il donne du pouvoir.","documents":[{"id":"titres","type":"tableau","titre":"Deux titres possibles","source":"Chiffres imaginés pour l’exercice.","colonnes":["","Action","Obligation"],"lignes":[["Prix d’un titre (€)",50,1000],["Rémunération","Dividende de 2 € par an","Intérêt de 4 % par an"],["Droit de vote","Oui","Non"],["Récupérer sa mise","Se revend","Remboursée à l’échéance"]],"enteteLignes":true},{"id":"capital","type":"tableau","titre":"Le capital de la brasserie","source":"Chiffres imaginés pour l’exercice.","colonnes":["Détenteur","Actions détenues"],"lignes":[["Le fondateur",600],["Les autres actionnaires",400]],"enteteLignes":true}],"questions":[{"enonce":"Associe chaque titre à sa nature.","aide":"L’actionnaire possède une part de l’entreprise ; l’obligataire lui a prêté de l’argent.","type":"association","gauche":[{"id":"g0","texte":"Une action"},{"id":"g1","texte":"Une obligation"}],"droite":[{"id":"d0","texte":"Un titre de créance"},{"id":"d1","texte":"Un titre de propriété"}]},{"enonce":"Quel intérêt annuel rapporte une obligation de 1 000 € ?","aide":"Calcule 4 % de 1 000 €.","type":"nombre","unite":"€"},{"enonce":"Touche la case qui explique comment un actionnaire récupère sa mise.","aide":"Regarde la dernière ligne, colonne « Action ».","type":"zone","document":"titres","multiple":false},{"enonce":"La brasserie émet 500 actions nouvelles, achetées par d’autres. Quelle part du capital le fondateur détient-il alors, en % ?","aide":"Il garde 600 actions, mais le total passe de 1 000 à 1 500.","type":"nombre","unite":"%"},{"enonce":"Que retenir de cette émission d’actions pour le fondateur ?","aide":"Compare la part du fondateur avant et après l’émission.","type":"choix","options":[{"id":"a","texte":"Il paie un intérêt fixe à chaque nouvel actionnaire"},{"id":"b","texte":"Il doit rembourser chaque action à l’échéance"},{"id":"c","texte":"Il finance son usine sans rien perdre de son contrôle"},{"id":"d","texte":"Il finance son usine mais voit son contrôle dilué"}],"multiple":false}]}$ex$::jsonb,
