   $ex${"titre":"Pourquoi l’État emprunte moins cher que la PME","competence":"lire-graphique","situation":"Une banque affiche ses taux pour un prêt de 5 ans, puis pour un État solide selon la durée. Maya veut comprendre pourquoi les taux ne sont pas les mêmes pour tous.","documents":[{"id":"taux","type":"tableau","titre":"Taux demandés pour un prêt de 5 ans","source":"Taux imaginés pour l’exercice.","colonnes":["Emprunteur","Taux d’intérêt (%)"],"lignes":[["État solide",2.5],["Grande entreprise solide",3],["PME fragile",6.5]],"enteteLignes":true},{"id":"duree","type":"graphique","forme":"courbe","titre":"Taux demandé à un État solide selon la durée du prêt","source":"Taux imaginés pour l’exercice.","categories":["1 an","2 ans","5 ans","10 ans","20 ans"],"series":[{"nom":"Taux","valeurs":[1,1.4,2,2.6,3.2],"teinte":"violet"}],"axeY":{"titre":"Taux d’intérêt","unite":"en %","min":0,"max":4,"pas":1},"axeX":{"titre":"Durée du prêt"}}],"questions":[{"enonce":"Touche l’emprunteur à qui la banque demande le taux le plus élevé.","aide":"Cherche le plus grand nombre de la colonne de droite.","type":"zone","document":"taux","multiple":false},{"enonce":"Quel écart, en points de pourcentage, sépare le taux de la PME fragile de celui de l’État solide ?","aide":"Soustrais les deux taux : 6,5 − 2,5.","type":"nombre","unite":"points"},{"enonce":"Lis sur le graphique le taux demandé à l’État solide pour un prêt de 10 ans.","aide":"Repère « 10 ans » sur l’axe horizontal puis lis la hauteur du point.","type":"nombre","unite":"%"},{"enonce":"Pourquoi un prêt plus long est-il généralement plus cher ?","aide":"Que peut-il se passer en vingt ans que l’on ne sait pas prévoir ?","type":"choix","options":[{"id":"a","texte":"L’emprunteur a plus de temps pour s’enrichir"},{"id":"b","texte":"L’incertitude sur l’avenir est plus grande"},{"id":"c","texte":"La banque doit garder plus de billets en caisse"},{"id":"d","texte":"Le taux directeur baisse avec la durée"}],"multiple":false}]}$ex$::jsonb,
