es obligatoires"},{"id":"g2","texte":"Les ratios de Bâle III"},{"id":"g3","texte":"La demande de crédit"}],"droite":[{"id":"d0","texte":"Un dépôt à la banque centrale"},{"id":"d1","texte":"Pas de prêt si personne n’emprunte"},{"id":"d2","texte":"Des fonds propres proportionnés aux risques"},{"id":"d3","texte":"Être couvertes en monnaie centrale"}]}]}$ex$::jsonb,
