   $ex${"titre":"Une journée de Maëlle, 8 ans","competence":"analyser-texte","situation":"Maëlle a 8 ans. Au fil d’une journée ordinaire, elle apprend des règles et des façons de faire auprès de plusieurs personnes. Voyons qui lui transmet quoi.","documents":[{"id":"journee","type":"texte","genre":"recit","titre":"Une journée ordinaire","source":"Récit écrit pour l’exercice.","blocs":["À la maison, le père de Maëlle lui rappelle de dire merci. Quand elle le fait, il la félicite.","À l’école, elle apprend à arriver à l’heure et à lever la main avant de parler.","À la récréation, ses copines décident que seules celles qui connaissent la dernière chanson peuvent jouer avec elles.","Le soir, elle imite la coiffure d’une youtubeuse qu’elle regarde sur la tablette."]}],"questions":[{"enonce":"Touche le mot qui montre une récompense donnée par le père.","aide":"Cherche ce que fait le père quand Maëlle dit merci.","type":"zone","document":"journee","multiple":false},{"enonce":"Range chaque scène selon l’instance de socialisation à l’œuvre.","aide":"Qui agit dans chaque phrase : le père, l’enseignante, les copines, une vidéo ?","type":"categories","categories":[{"id":"c0","texte":"La famille"},{"id":"c1","texte":"L’école"},{"id":"c2","texte":"Les pairs"},{"id":"c3","texte":"Les médias"}],"items":[{"id":"i0","texte":"Elle apprend à arriver à l’heure"},{"id":"i1","texte":"Elle imite une youtubeuse"},{"id":"i2","texte":"Le père rappelle de dire merci"},{"id":"i3","texte":"Ses copines imposent leurs codes de jeu"}]},{"enonce":"Comment Maëlle apprend-elle la coiffure de la youtubeuse ?","aide":"Personne ne lui dit de le faire ; elle regarde, puis copie.","type":"choix","options":[{"id":"a","texte":"Par imitation : elle reproduit ce qu’elle observe"},{"id":"b","texte":"Par inculcation : on énonce la règle et on sanctionne"},{"id":"c","texte":"Par interaction : elle négocie la règle avec ses parents"},{"id":"d","texte":"Par institution totale : elle vit dans un lieu fermé"}],"multiple":false},{"enonce":"Associe chaque exemple de la journée à la notion de socialisation.","aide":"Idéal, règle concrète, comportement attendu.","type":"association","gauche":[{"id":"g0","texte":"L’égalité"},{"id":"g1","texte":"Lever la main avant de parler"},{"id":"g2","texte":"L’élève"}],"droite":[{"id":"d0","texte":"Un rôle : un comportement attendu"},{"id":"d1","texte":"Une valeur : un idéal partagé"},{"id":"d2","texte":"Une norme : la règle concrète"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"Le père la **félicite** : l’inculcation explicite passe par la récompense et la sanction."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c3","i2":"c0","i3":"c2"}},"explication":"La **famille** est la première instance ; l’**école** transmet ponctualité et règle impersonnelle ; les **pairs** imposent leurs codes ; les **médias** offrent des modèles."},{"cle":{"type":"choix","ids":["a"]},"explication":"**L’imitation** : l’enfant reproduit ce qu’il observe."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Une **valeur** est un idéal ; une **norme**, la règle concrète qui la traduit ; un **rôle**, le comportement attendu de celui qui occupe une position."}]$ex$::jsonb),
  ('0ad4ab27-2baa-59e9-904d-da23069a7258'::uuid, 2, 2, 10, 35, 5,
