  ('0ad4ab27-2baa-59e9-904d-da23069a7258'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Des goûts qui semblent aller de soi","competence":"argumenter","situation":"Adrien, 17 ans, raconte qu’il passe toujours, sans y réfléchir, devant les mêmes rayons de la librairie. Il se demande d’où viennent ces goûts. À toi de relier son témoignage aux notions du cours.","documents":[{"id":"adrien","type":"texte","genre":"lettre","titre":"Le témoignage d’Adrien","source":"Témoignage écrit pour l’exercice.","blocs":["Chez moi, on parlait de livres à table et on passait le dimanche à la médiathèque. Aujourd’hui, je me retrouve automatiquement au rayon des essais, sans me demander pourquoi. Mon cousin, lui, va tout droit au rayon des jeux vidéo."]},{"id":"notions","type":"tableau","titre":"Ce que la socialisation transmet","source":"Exemples écrits pour l’exercice.","colonnes":["Contenu transmis","Exemple"],"lignes":[["La réussite","Un idéal partagé"],["Respecter la file d’attente","Une règle de conduite"],["Être un bon élève","Un comportement attendu"],["L’égalité","Un idéal partagé"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui montre qu’Adrien agit sans y penser.","aide":"Cherche l’adverbe qui décrit sa façon d’aller au rayon.","type":"zone","document":"adrien","multiple":false},{"enonce":"Comment Bourdieu nomme-t-il l’ensemble de ces dispositions durables incorporées par la socialisation ?","aide":"Il s’agit d’un mot de Bourdieu qui désigne les dispositions durables.","type":"choix","options":[{"id":"a","texte":"La norme"},{"id":"b","texte":"L’alternation"},{"id":"c","texte":"Le capital économique"},{"id":"d","texte":"L’habitus"}],"multiple":false},{"enonce":"Range chaque contenu transmis dans sa notion : valeur, norme ou rôle.","aide":"Le tableau donne un indice dans la deuxième colonne.","type":"categories","categories":[{"id":"c0","texte":"Valeur"},{"id":"c1","texte":"Norme"},{"id":"c2","texte":"Rôle"}],"items":[{"id":"i0","texte":"Respecter la file d’attente"},{"id":"i1","texte":"La réussite"},{"id":"i2","texte":"L’égalité"},{"id":"i3","texte":"Être un bon élève"}]},{"enonce":"Adrien et son cousin ont des goûts très différents. Selon le cours, qu’est-ce qui peut l’expliquer ?","aide":"Les mêmes instances ne transmettent pas les mêmes contenus partout.","type":"choix","options":[{"id":"a","texte":"Une même socialisation reçue par les deux cousins"},{"id":"b","texte":"Une absence totale de socialisation chez l’un d’eux"},{"id":"c","texte":"Des goûts innés identiques que seul le hasard change"},{"id":"d","texte":"Des socialisations différentes, selon le milieu"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m20"]},"explication":"**Automatiquement** : ses dispositions sont incorporées, elles orientent ses choix sans qu’il ait à y penser."},{"cle":{"type":"choix","ids":["d"]},"explication":"**L’habitus** : des dispositions durables, incorporées, qui orientent goûts, gestes et choix."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c2"}},"explication":"**Valeur** : idéal partagé. **Norme** : règle concrète. **Rôle** : comportement attendu de celui qui occupe une position."},{"cle":{"type":"choix","ids":["d"]},"explication":"Selon le **milieu social** et le **genre**, les mêmes instances transmettent des contenus différents : la socialisation **ne produit pas des individus identiques**."}]$ex$::jsonb),
