  ('11fcea04-d4d3-5613-b399-56bd45aa86ea'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Camille rêve d’une école de commerce","competence":"analyser-texte","situation":"Camille, 17 ans, rêve d’entrer dans une école de commerce très sélective. Elle ne la connaît pas encore, mais elle se prépare déjà. Un tableau donne les chiffres du concours.","documents":[{"id":"camille","type":"texte","genre":"recit","titre":"Se préparer avant d’y entrer","source":"Récit écrit pour l’exercice.","blocs":["Camille vient d’un village où personne n’a fait de longues études. Dans l’espoir d’entrer à l’école de commerce, elle lit chaque jour la presse économique, change sa façon de s’habiller et adopte le vocabulaire des étudiants qu’elle suit en ligne."]},{"id":"concours","type":"tableau","titre":"Le concours d’entrée","source":"Chiffres imaginés pour l’exercice.","colonnes":["Candidats","Places"],"lignes":[[600,40]],"enteteLignes":false}],"questions":[{"enonce":"Touche le mot qui montre que Camille n’appartient pas encore au groupe qu’elle imite.","aide":"Cherche le mot qui dit qu’elle compte y entrer plus tard.","type":"zone","document":"camille","multiple":false},{"enonce":"Quel nom donne-t-on à ce que fait Camille, mis en évidence par Merton ?","aide":"Elle adopte à l’avance les normes d’un groupe qu’elle espère rejoindre.","type":"choix","options":[{"id":"a","texte":"La socialisation primaire"},{"id":"b","texte":"L’institution totale"},{"id":"c","texte":"La socialisation anticipatrice"},{"id":"d","texte":"L’alternation"}],"multiple":false},{"enonce":"Combien de candidats ne seront pas admis ?","aide":"Soustrais le nombre de places au nombre de candidats.","type":"nombre","unite":"candidats"},{"enonce":"Quel est le taux d’admission, en % ? Arrondis au dixième.","aide":"Divise 40 par 600.","type":"nombre","unite":"%"},{"enonce":"Que risque Camille si elle n’est pas admise ?","aide":"Elle a pris des habitudes d’un groupe qui ne l’a pas accueillie.","type":"choix","options":[{"id":"a","texte":"Retrouver instantanément ses dispositions d’enfance"},{"id":"b","texte":"Rester en porte-à-faux entre deux groupes"},{"id":"c","texte":"Être resocialisée dans une institution totale"},{"id":"d","texte":"Perdre toute trace de socialisation primaire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"Dans l’**espoir** d’entrer : elle intériorise déjà les normes d’un groupe qu’elle n’a pas rejoint."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est la **socialisation anticipatrice** (**Merton**) : intérioriser les normes d’un groupe auquel on n’appartient pas encore."},{"cle":{"type":"nombre","valeur":560,"tolerance":0},"affichage":"560 candidats","explication":"600 − 40 = **560 candidats**."},{"cle":{"type":"nombre","valeur":6.7,"tolerance":0.1},"affichage":"6,7 %","explication":"40 ÷ 600 ≈ 0,067, soit environ **6,7 %**."},{"cle":{"type":"choix","ids":["b"]},"explication":"La socialisation anticipatrice facilite la mobilité, mais laisse **en porte-à-faux** celui qui **n’est finalement pas admis**."}]$ex$::jsonb),
  ('11fcea04-d4d3-5613-b399-56bd45aa86ea'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Prolonger ou rompre : trois trajectoires","competence":"raisonner","situation":"Trois personnes imaginaires ont vécu une socialisation secondaire très différente de leur socialisation primaire, ou très proche. Un témoignage montre ce que ressent l’une d’elles.","documents":[{"id":"portraits","type":"tableau","titre":"Trois trajectoires","source":"Portraits imaginés pour l’exercice.","colonnes":["Personne","Milieu d’origine","Ensuite"],"lignes":[["Sarah","Fille d’agriculteurs","Reprend l’exploitation familiale"],["Malik","Fils d’ouvrier","Devient cadre dans une banque"],["Paul","Famille sans pratique religieuse","Entre au monastère après une conversion"]],"enteteLignes":true},{"id":"malik","type":"texte","genre":"lettre","titre":"Le témoignage de Malik","source":"Témoignage écrit pour l’exercice.","blocs":["Au bureau, on me dit que je parle comme les autres cadres. À la maison, mes frères me demandent pourquoi je me prends pour quelqu’un d’autre. Je ne sais plus très bien où est ma place."]}],"questions":[{"enonce":"Touche le portrait d’une mobilité sociale ascendante.","aide":"Cherche celui dont le milieu d’arrivée est plus favorisé que celui de départ.","type":"zone","document":"portraits","multiple":false},{"enonce":"La socialisation secondaire prolonge-t-elle ou contredit-elle la primaire ?","aide":"Pour chaque portrait, compare le milieu d’origine à ce que la personne devient.","type":"categories","categories":[{"id":"c0","texte":"Elle prolonge"},{"id":"c1","texte":"Elle contredit"}],"items":[{"id":"i0","texte":"Malik devient cadre dans une banque"},{"id":"i1","texte":"Sarah reprend l’exploitation familiale"},{"id":"i2","texte":"Paul entre au monastère après une conversion"}]},{"enonce":"Quel terme de Berger et Luckmann décrit une nouvelle socialisation qui doit d’abord démolir l’ancienne, comme pour Paul ?","aide":"Ce mot désigne une rupture et une resocialisation.","type":"choix","options":[{"id":"a","texte":"L’alternation"},{"id":"b","texte":"La socialisation anticipatrice"},{"id":"c","texte":"L’interaction"},{"id":"d","texte":"L’habitus"}],"multiple":false},{"enonce":"Que montre le témoignage de Malik sur le rapport entre les deux socialisations ?","aide":"Malik se sent entre deux mondes : à la banque et à la maison.","type":"choix","options":[{"id":"a","texte":"La seconde a effacé entièrement la première"},{"id":"b","texte":"La première n’a jamais eu d’effet sur Malik"},{"id":"c","texte":"Elles se superposent : la seconde ne remplace pas la première"},{"id":"d","texte":"La première se réduit à la socialisation scolaire"}],"multiple":false}]}$ex$::jsonb,
