 sais.","type":"choix","options":[{"id":"a","texte":"Ils apportent une information nouvelle, venue d’un autre milieu"},{"id":"b","texte":"Ils sont plus chaleureux et plus fiables que les liens forts"},{"id":"c","texte":"Ils obligent les employeurs à recruter dans un cercle fermé"},{"id":"d","texte":"Ils sont plus nombreux et se connaissent tous entre eux"}],"multiple":false}]}$ex$::jsonb,
