   $ex${"titre":"Fumer : une norme qui a changé","competence":"analyser-document","situation":"Le journal d’un lycée imaginaire raconte comment le regard porté sur la cigarette a changé en quarante ans. Un sondage imaginé chiffre ce changement.","documents":[{"id":"journal","type":"texte","genre":"article","titre":"Fumer au lycée : avant et maintenant","auteur":"Texte écrit pour l’exercice","blocs":["En 1985, les professeurs fumaient en salle des professeurs et parfois en classe, sans que personne n’y trouve à redire. Aujourd’hui, allumer une cigarette devant l’entrée du lycée attire un regard réprobateur et une remarque des élèves.","Entre-temps, l’interdiction de fumer dans les lieux publics, entrée en vigueur en 2007, est venue appuyer un changement déjà engagé : fumer n’est plus perçu comme anodin."]},{"id":"sondage","type":"tableau","titre":"Fumer devant des enfants : est-ce acceptable ?","source":"Sondage imaginé pour l’exercice.","colonnes":["Année","Personnes qui jugent cela acceptable (%)"],"lignes":[[1990,62],[2005,35],[2022,8]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux mots qui désignent la forme de contrôle informel décrite dans le texte.","aide":"Cherche ce que les élèves expriment par leur attitude avant toute parole.","type":"zone","document":"journal","multiple":true},{"enonce":"De combien de points de pourcentage l’acceptation a-t-elle baissé entre 1990 et 2022 ?","aide":"Soustrais la dernière valeur à la première.","type":"nombre","unite":"points"},{"enonce":"Range chaque moyen selon la forme de contrôle qu’il représente.","aide":"Une règle écrite et une sanction codifiée relèvent du formel.","type":"categories","categories":[{"id":"c0","texte":"Contrôle formel"},{"id":"c1","texte":"Contrôle informel"}],"items":[{"id":"i0","texte":"Une amende pour avoir fumé là où c’est interdit"},{"id":"i1","texte":"Un regard réprobateur à la sortie du lycée"},{"id":"i2","texte":"La remarque d’un camarade"},{"id":"i3","texte":"L’interdiction de fumer dans les lieux publics"}]},{"enonce":"Que montre l’évolution du regard porté sur le tabac ?","aide":"Fumer en classe était banal en 1985.","type":"choix","options":[{"id":"a","texte":"Le contrôle social disparaît quand la norme est écrite"},{"id":"b","texte":"La déviance est une qualité propre à l’acte lui-même"},{"id":"c","texte":"Une norme ne change jamais sans nouvelle loi"},{"id":"d","texte":"Une même conduite peut changer de statut normatif selon l’époque"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Pense au cours : trois critères.","type":"trous","segments":["Une même conduite est déviante ou non selon la ",0,", l’",1," et le groupe qui juge."],"banque":["âge","société","loi","époque"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m32","m33"]},"explication":"Le **regard réprobateur** est du contrôle social informel : une sanction diffuse de l’entourage."},{"cle":{"type":"nombre","valeur":54,"tolerance":0},"affichage":"54 points","explication":"62 − 8 = **54 points de pourcentage**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"Loi et amende sont du contrôle **formel** (règles écrites, sanction codifiée). Regard et remarque sont du contrôle **informel** (entourage, sanction diffuse)."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le contrôle ne fait pas qu’empêcher la déviance : **il la définit**. Le tabac, le duel ou l’homosexualité ont changé de statut normatif."},{"cle":{"type":"trous","trous":[["societe"],["epoque"]]},"affichage":"société · époque","explication":"La déviance dépend de la **société**, de l’**époque** et du groupe qui juge."}]$ex$::jsonb),
  ('ce4a2bc5-d848-580a-b29c-54d2a5d9ed15'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Pyjama, scooter et tag : déviance ou délinquance ?","competence":"lire-tableau","situation":"Quatre comportements sont notés dans un carnet d’observation. Pour chacun, on a relevé si une norme sociale et une loi pénale sont transgressées.","documents":[{"id":"conduites","type":"tableau","titre":"Quatre conduites","source":"Observations imaginées pour l’exercice.","colonnes":["Comportement","Norme sociale transgressée","Loi pénale transgressée"],"lignes":[["Un adulte vient en pyjama au restaurant","Oui","Non"],["Un homme vole un scooter","Oui","Oui"],["Un spectateur rit très fort pendant une scène tragique","Oui","Non"],["Un adolescent tague le mur d’une école","Oui","Oui"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux comportements qui sont déviants sans être délinquants.","aide":"Cherche les lignes où la loi pénale n’est pas transgressée.","type":"zone","document":"conduites","multiple":true},{"enonce":"Range chaque comportement.","aide":"La délinquance transgresse une norme juridique, pénalement sanctionnée.","type":"categories","categories":[{"id":"c0","texte":"Déviant sans être délinquant"},{"id":"c1","texte":"Délinquant (donc aussi déviant)"}],"items":[{"id":"i0","texte":"Taguer le mur d’une école"},{"id":"i1","texte":"Voler un scooter"},{"id":"i2","texte":"Rire très fort pendant une scène tragique"},{"id":"i3","texte":"Venir en pyjama au restaurant"}]},{"enonce":"Quelle phrase résume la relation entre déviance et délinquance ?","aide":"Regarde combien de comportements transgressent la loi parmi ceux qui transgressent une norme sociale.","type":"choix","options":[{"id":"a","texte":"La délinquance est plus large que la déviance"},{"id":"b","texte":"La déviance et la délinquance désignent exactement la même chose"},{"id":"c","texte":"Toute délinquance est déviante, mais toute déviance n’est pas délinquante"},{"id":"d","texte":"Toute déviance est une délinquance, mais l’inverse est faux"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0","r2c0"]},"explication":"Le **pyjama au restaurant** et le **rire pendant une scène tragique** transgressent une norme sociale mais aucune loi : ce sont des déviances, pas des délinquances."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Voler un scooter et tagger un mur transgressent la **loi pénale** : c’est de la délinquance. Les deux autres ne transgressent que des normes sociales."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Toute délinquance est déviante, l’inverse est faux** : la déviance est large (toute norme sociale), la délinquance étroite (la loi pénale)."}]$ex$::jsonb),
  ('ce4a2bc5-d848-580a-b29c-54d2a5d9ed15'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Cinq façons de réagir à la réussite","competence":"analyser-document","situation":"Dans une société qui valorise la réussite, tout le monde n’a pas les mêmes moyens légitimes d’y parvenir. Merton décrit cinq adaptations ; cinq personnes imaginées illustrent chacune l’une d’elles.","documents":[{"id":"portraits","type":"texte","genre":"recit","titre":"Cinq portraits","auteur":"Texte écrit pour l’exercice","blocs":["Samir, 22 ans, rêve de réussir financièrement. Faute de diplôme, il revend des contrefaçons sur les marchés.","Clara, guichetière, applique chaque règle à la lettre mais n’attend plus aucune promotion.","Maël a cessé de chercher du travail et vit en marge, sans ambition de réussite.","Anaïs a fondé une coopérative qui refuse la course au profit et cherche à changer les règles du jeu.","Jordan a fait ses études, décroché son diplôme et occupe l’emploi qu’il visait."]},{"id":"merton","type":"tableau","titre":"Les adaptations de Merton","source":"D’après la typologie de Robert K. Merton.","colonnes":["Adaptation","Buts valorisés","Moyens légitimes"],"lignes":[["Conformité","Acceptés","Acceptés"],["Innovation","Acceptés","Rejetés"],["Ritualisme","Rejetés","Acceptés"],["Évasion","Rejetés","Rejetés"],["Rébellion","Remplacés","Remplacés"]],"enteteLignes":true}],"questions":[{"enonce":"Relie chaque personne à l’adaptation de Merton qu’elle illustre.","aide":"Demande-toi : garde-t-il le but ? utilise-t-il les moyens légitimes ?","type":"association","gauche":[{"id":"g0","texte":"Samir"},{"id":"g1","texte":"Clara"},{"id":"g2","texte":"Maël"},{"id":"g3","texte":"Anaïs"},{"id":"g4","texte":"Jordan"}],"droite":[{"id":"d0","texte":"Innovation"},{"id":"d1","texte":"Rébellion"},{"id":"d2","texte":"Conformité"},{"id":"d3","texte":"Ritualisme"},{"id":"d4","texte":"Évasion"}]},{"enonce":"Touche ce que Samir fait des moyens légitimes, dans le tableau.","aide":"Samir est dans la ligne « Innovation » : lis la colonne des moyens.","type":"zone","document":"merton","multiple":false},{"enonce":"Range chaque adaptation.","aide":"Regarde la colonne « Buts valorisés » du tableau.","type":"categories","categories":[{"id":"c0","texte":"Garde le but valorisé"},{"id":"c1","texte":"Abandonne ou remplace le but"}],"items":[{"id":"i0","texte":"Conformité"},{"id":"i1","texte":"Évasion"},{"id":"i2","texte":"Rébellion"},{"id":"i3","texte":"Innovation"},{"id":"i4","texte":"Ritualisme"}]},{"enonce":"Selon Merton, d’où naît la déviance ?","aide":"C’est l’idée centrale de son explication.","type":"choix","options":[{"id":"a","texte":"De l’étiquette qu’un groupe applique à un individu déjà transgressif"},{"id":"b","texte":"De l’écart entre les buts valorisés et les moyens légitimes d’y accéder"},{"id":"c","texte":"De l’absence totale de buts partagés dans toute la société moderne"},{"id":"d","texte":"De la volonté consciente de braver tous les interdits de la société"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g4":"d2","g1":"d3","g2":"d4"}},"explication":"Samir poursuit le but par des moyens illégitimes : **innovation**. Clara garde les moyens sans le but : **ritualisme**. Maël rejette les deux : **évasion**. Anaïs remplace buts et moyens : **rébellion**. Jordan : **conformité**."},{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Samir **rejette les moyens légitimes** (il n’y a pas accès) tout en gardant le but : c’est l’innovation."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c1"}},"explication":"**Conformité** et **innovation** gardent le but. Ritualisme, évasion et rébellion l’abandonnent ou le remplacent."},{"cle":{"type":"choix","ids":["b"]},"explication":"Pour Merton, la déviance naît de l’**écart entre les buts valorisés et les moyens légitimes**, inégalement distribués."}]$ex$::jsonb),
  ('ce4a2bc5-d848-580a-b29c-54d2a5d9ed15'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Mathis : de l’absence à l’étiquette","competence":"raisonner","situation":"Mathis, 14 ans, sèche des cours. Son parcours imaginé permet de suivre ce que Becker appelle une carrière déviante, avec le nombre de ses absences.","documents":[{"id":"mathis","type":"texte","genre":"recit","titre":"Le parcours de Mathis","auteur":"Texte écrit pour l’exercice","blocs":["Au début de l’automne, Mathis sèche quelques cours : un acte banal, que beaucoup d’élèves ont déjà commis.","En novembre, la CPE le convoque, son professeur principal le range parmi les « décrocheurs » et plusieurs camarades prennent leurs distances. On ne lui confie plus de responsabilités et l’on s’attend à ce qu’il continue.","Isolé, il se rapproche d’autres élèves étiquetés comme lui, qui sèchent ensemble et lui apprennent à ne plus s’en cacher."]},{"id":"absences","type":"graphique","forme":"barres","titre":"Absences injustifiées de Mathis","source":"Chiffres imaginés pour l’exercice.","categories":["Sept.","Oct.","Nov.","Déc."],"series":[{"nom":"Demi-journées d’absence","valeurs":[2,3,9,15],"teinte":"corail"}],"axeY":{"titre":"Absences","unite":"demi-journées","min":0,"max":16,"pas":4},"valeurs":false}],"questions":[{"enonce":"Remets dans l’ordre les étapes de la carrière déviante de Mathis.","aide":"Relis le texte paragraphe par paragraphe.","type":"ordre","items":[{"id":"a","texte":"La stigmatisation"},{"id":"b","texte":"La transgression initiale"},{"id":"c","texte":"L’entrée dans un groupe déviant"},{"id":"d","texte":"La réaction sociale"}]},{"enonce":"Touche le mois où la réaction sociale commence.","aide":"Le texte date la convocation de la CPE.","type":"zone","document":"absences","multiple":false},{"enonce":"En novembre, combien de fois plus d’absences qu’en octobre Mathis compte-t-il ?","aide":"Divise le nombre d’absences de novembre par celui d’octobre.","type":"nombre","unite":"fois"},{"enonce":"Comment Becker interprète-t-il cette accélération ?","aide":"Que se passe-t-il quand on s’attend à ce qu’il continue ?","type":"choix","options":[{"id":"a","texte":"Une exclusion plus rapide aurait empêché toute rechute"},{"id":"b","texte":"L’étiquette finit par produire le comportement qu’elle désigne"},{"id":"c","texte":"La hausse vient surtout de la baisse des moyens légitimes"},{"id":"d","texte":"Mathis a toujours eu plus d’absences qu’il ne l’avoue"}],"multiple":false},{"enonce":"Relie chaque auteur à son explication de la déviance.","aide":"Pense à ce que chacun place au centre : normes, moyens, réaction.","type":"association","gauche":[{"id":"g0","texte":"Durkheim"},{"id":"g1","texte":"Merton"},{"id":"g2","texte":"Becker"}],"droite":[{"id":"d0","texte":"L’écart entre les buts et les moyens légitimes"},{"id":"d1","texte":"L’anomie : l’affaiblissement des normes collectives"},{"id":"d2","texte":"L’étiquetage par la réaction sociale"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"ordre","ids":["b","d","a","c"]},"explication":"Transgression banale, puis **réaction sociale** (le groupe étiquette), puis **stigmatisation** (les portes se ferment), puis entrée dans un **groupe déviant** qui fournit à son tour des normes."},{"cle":{"type":"zone","ids":["k2"]},"explication":"La réaction sociale commence en **novembre** : convocation, étiquette de « décrocheur », distance des camarades."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 fois","explication":"9 ÷ 3 = **3 fois** plus : les absences s’accélèrent après l’étiquetage."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est une **prophétie auto-réalisatrice** : l’étiquette de déviant produit ce qu’elle prétend décrire."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"**Durkheim** : anomie. **Merton** : écart buts-moyens. **Becker** : étiquetage. Merton explique l’exposition à la transgression, Becker l’aggravation par le traitement social."}]$ex$::jsonb),
  ('6ac8a48f-266f-546b-809a-04e78c2cff76'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Plaintes ou victimes : deux chiffres pour une même ville","competence":"lire-tableau","situation":"Dans une ville imaginée de 100 000 habitants, la police a compté les plaintes enregistrées en un an. Une enquête de victimation a demandé à un échantillon d’habitants ce qu’ils avaient subi.","documents":[{"id":"deux","type":"tableau","titre":"Plaintes et victimes déclarées","source":"Chiffres imaginés pour l’exercice.","colonnes":["Infraction","Plaintes enregistrées","Victimes déclarées dans l’enquête"],"lignes":[["Vols de voiture",480,500],["Cambriolages",300,600],["Violences au sein du couple",120,900]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’infraction pour laquelle l’écart entre plaintes et victimes déclarées est le plus grand.","aide":"Calcule la différence entre les deux colonnes pour chaque ligne.","type":"zone","document":"deux","multiple":false},{"enonce":"Combien de victimes de violences au sein du couple n’apparaissent pas dans les plaintes ?","aide":"Soustrais les plaintes aux victimes déclarées.","type":"nombre","unite":"victimes"},{"enonce":"Comment s’appelle l’écart entre la délinquance réelle et la délinquance enregistrée ?","aide":"Il n’est jamais mesuré directement.","type":"choix","options":[{"id":"a","texte":"La nomenclature"},{"id":"b","texte":"Le taux de victimation"},{"id":"c","texte":"Le chiffre noir"},{"id":"d","texte":"La marge d’erreur"}],"multiple":false},{"enonce":"Quelle part des vols de voiture déclarés dans l’enquête a donné lieu à une plainte ? Réponds en pourcentage.","aide":"Divise les plaintes par les victimes déclarées, puis multiplie par 100.","type":"nombre","unite":"%"}]}$ex$::jsonb,
