  ('6ac8a48f-266f-546b-809a-04e78c2cff76'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une opération radar : plus de contrôles, plus d’infractions","competence":"analyser-document","situation":"Dans un département imaginaire, les gendarmes ont renforcé les contrôles de vitesse en avril. Le tableau donne les chiffres de trois mois.","documents":[{"id":"controles","type":"tableau","titre":"Contrôles de vitesse","source":"Chiffres imaginés pour l’exercice.","colonnes":["Mois","Contrôles de vitesse","Infractions constatées"],"lignes":[["Mars",2000,100],["Avril (opération renforcée)",6000,240],["Mai",3000,150]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mois où l’on constate le plus d’infractions.","aide":"Lis la dernière colonne.","type":"zone","document":"controles","multiple":false},{"enonce":"En avril, quelle part des contrôles a révélé une infraction ? Réponds en pourcentage.","aide":"Divise 240 par 6 000 puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Que prouve la hausse des infractions constatées en avril ?","aide":"Compare le nombre de contrôles et la part d’infractions.","type":"choix","options":[{"id":"a","texte":"Elle prouve que les conducteurs ont roulé plus vite en avril"},{"id":"b","texte":"Elle dépend surtout de l’activité des services, pas d’une hausse des excès"},{"id":"c","texte":"Elle montre que les statistiques de police sont toutes fausses"},{"id":"d","texte":"Elle prouve que le chiffre noir a disparu dans le département"}],"multiple":false},{"enonce":"Range chaque facteur selon son effet sur les statistiques.","aide":"Demande-toi : les comportements ont-ils vraiment changé ?","type":"categories","categories":[{"id":"c0","texte":"Change la statistique sans changer les comportements"},{"id":"c1","texte":"Reflète un changement réel des comportements"}],"items":[{"id":"i0","texte":"Une campagne qui encourage à porter plainte"},{"id":"i1","texte":"Plus de vols effectivement commis"},{"id":"i2","texte":"Une loi qui transforme un acte en délit"},{"id":"i3","texte":"Davantage de patrouilles dans les rues"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"En **avril**, 240 infractions sont constatées : la valeur la plus élevée."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 %","explication":"240 ÷ 6 000 = 0,04, soit **4 %**. En mars et en mai, la part est de 5 % : l’excès de vitesse n’a pas augmenté."},{"cle":{"type":"choix","ids":["b"]},"explication":"Plus de contrôles produisent **mécaniquement** plus d’infractions constatées. La part d’infractions (4 %) n’a même pas augmenté."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Activité des services, changement de législation et propension à porter plainte modifient les **statistiques** sans que les comportements changent. Seule une hausse réelle des vols reflète un changement des comportements."}]$ex$::jsonb),
  ('6ac8a48f-266f-546b-809a-04e78c2cff76'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Violences conjugales : que dit la hausse des plaintes ?","competence":"analyser-document","situation":"Dans le département imaginaire de l’Ardoise, les plaintes pour violences au sein du couple augmentent. Un article et une enquête de victimation imaginée permettent de lire cette hausse.","documents":[{"id":"victimation","type":"tableau","titre":"Enquête de victimation et plaintes (pour 1 000 habitants)","source":"Chiffres imaginés pour l’exercice.","colonnes":["Atteinte","Victimes déclarées dans l’enquête","Plaintes enregistrées"],"lignes":[["Vol de voiture",10,9],["Cambriolage",20,10],["Violences sexuelles",8,0.8],["Violences au sein du couple",12,1.8]],"enteteLignes":true},{"id":"presse","type":"texte","genre":"article","titre":"Les plaintes pour violences conjugales en hausse","auteur":"Article imaginé pour l’exercice","blocs":["Dans l’Ardoise, les plaintes pour violences au sein du couple ont augmenté de 20 % en trois ans.","Pour la préfecture, la hausse prouve que ces violences se multiplient. Pour les associations d’aide aux victimes, elle s’explique d’abord par l’ouverture de deux commissariats spécialisés et par une campagne qui a encouragé les victimes à parler."]}],"questions":[{"enonce":"Touche l’atteinte dont le chiffre noir est le plus faible.","aide":"Cherche l’infraction où presque toutes les victimes déclarées portent plainte.","type":"zone","document":"victimation","multiple":false},{"enonce":"Quelle part des victimes de cambriolage déclarées dans l’enquête a porté plainte ? Réponds en pourcentage.","aide":"Divise les plaintes par les victimes déclarées.","type":"nombre","unite":"%"},{"enonce":"Range chaque limite selon la source de mesure qu’elle concerne.","aide":"L’une compte des plaintes, l’autre interroge un échantillon.","type":"categories","categories":[{"id":"c0","texte":"Statistiques administratives"},{"id":"c1","texte":"Enquêtes de victimation"}],"items":[{"id":"i0","texte":"Dépendent de l’activité des services"},{"id":"i1","texte":"Reposent sur le souvenir de l’enquêté"},{"id":"i2","texte":"Couvrent mal les infractions sans victime directe"},{"id":"i3","texte":"Ne comptent que ce qui est déclaré"}]},{"enonce":"Pour 1 000 habitants, combien de victimes de violences au sein du couple ne figurent pas dans les plaintes ?","aide":"Soustrais les plaintes aux victimes déclarées.","type":"nombre","unite":"victimes"},{"enonce":"Comment lire la hausse de 20 % des plaintes pour violences conjugales ?","aide":"Le chiffre noir est très élevé pour cette infraction.","type":"choix","options":[{"id":"a","texte":"Elle prouve avec certitude une baisse des violences réelles"},{"id":"b","texte":"Elle prouve avec certitude une hausse des violences réelles"},{"id":"c","texte":"Elle peut signaler plus de violences ou une meilleure prise de parole"},{"id":"d","texte":"Elle ne peut avoir aucune signification statistique"}],"multiple":false}]}$ex$::jsonb,
