  ('7e0ef681-b56b-55b9-b7ee-d2e5c34d4e13'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois projets, trois statuts","competence":"analyser-document","situation":"Trois projets imaginés cherchent leur statut juridique : une boulangerie, un livreur à vélo et une imprimerie reprise par ses salariés.","documents":[{"id":"projets","type":"texte","genre":"recit","titre":"Les trois projets","auteur":"Texte écrit pour l’exercice","blocs":["Amel ouvre une boulangerie avec deux associés. Elle veut que sa maison personnelle reste à l’abri si l’affaire fait faillite.","Hugo livre des repas à vélo : il travaille seul, sans local, et choisit un régime simplifié.","Douze salariés d’une imprimerie la reprennent ensemble : chacun aura une voix, quel que soit le capital qu’il apporte."]},{"id":"statuts","type":"tableau","titre":"Trois statuts","source":"D’après les statuts d’entreprise en France.","colonnes":["Statut","Patrimoine de l’entreprise séparé de celui du propriétaire ?","Pouvoir de décision"],"lignes":[["Entreprise individuelle (micro-entrepreneur)","Non","Un seul entrepreneur"],["SARL","Oui","Proportionnel au capital détenu"],["Coopérative","Oui","Une personne, une voix"]],"enteteLignes":true}],"questions":[{"enonce":"Relie chaque projet au statut qui lui correspond le mieux.","aide":"Qui veut protéger son patrimoine ? Qui travaille seul ? Qui veut une personne, une voix ?","type":"association","gauche":[{"id":"g0","texte":"La boulangerie d’Amel"},{"id":"g1","texte":"Le livreur Hugo"},{"id":"g2","texte":"L’imprimerie des salariés"}],"droite":[{"id":"d0","texte":"Entreprise individuelle"},{"id":"d1","texte":"Coopérative"},{"id":"d2","texte":"Société (SARL)"}]},{"enonce":"Touche la case qui décrit le pouvoir dans une coopérative.","aide":"Cherche la ligne « Coopérative » et la dernière colonne.","type":"zone","document":"statuts","multiple":false},{"enonce":"Range chaque statut selon le sort du patrimoine.","aide":"Les sociétés séparent le patrimoine de l’entreprise de celui des propriétaires.","type":"categories","categories":[{"id":"c0","texte":"Patrimoine de l’entreprise séparé"},{"id":"c1","texte":"Patrimoine de l’entrepreneur engagé"}],"items":[{"id":"i0","texte":"SA"},{"id":"i1","texte":"SARL"},{"id":"i2","texte":"Entreprise individuelle"},{"id":"i3","texte":"SAS"}]},{"enonce":"Que regroupe l’économie sociale et solidaire ?","aide":"Le profit n’y est pas la finalité.","type":"choix","options":[{"id":"a","texte":"Entreprises publiques détenues majoritairement par l’État"},{"id":"b","texte":"Grandes entreprises cotées en bourse et leurs filiales"},{"id":"c","texte":"Microentreprises et entreprises individuelles uniquement"},{"id":"d","texte":"Coopératives, mutuelles, associations et fondations"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Amel veut séparer son patrimoine : une **société**. Hugo travaille seul : **entreprise individuelle** (micro-entrepreneur). Les salariés veulent « une personne, une voix » : **coopérative**."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"Dans une coopérative, le pouvoir est **« une personne, une voix »**, et non proportionnel au capital."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Dans les **sociétés** (SARL, SAS, SA), le patrimoine de l’entreprise est séparé de celui des propriétaires. Dans l’**entreprise individuelle**, le patrimoine de l’entrepreneur est engagé."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’**économie sociale et solidaire** regroupe coopératives, mutuelles, associations et fondations : le profit n’y est pas la finalité, souvent « une personne, une voix »."}]$ex$::jsonb),
  ('7e0ef681-b56b-55b9-b7ee-d2e5c34d4e13'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Schumpeter, Knight et le bond des créations","competence":"raisonner","situation":"Quatre projets imaginés permettent de distinguer les figures de l’entrepreneur. Un tableau imaginé montre ensuite les effets d’un statut simplifié créé en 2008.","documents":[{"id":"entrepreneurs","type":"texte","genre":"recit","titre":"Quatre projets","auteur":"Texte écrit pour l’exercice","blocs":["Sacha invente un procédé qui sèche le bois deux fois plus vite.","Emma lance la vente de miel de montagne dans un pays où personne n’en vendait.","Théo rouvre à l’identique la boulangerie fermée de son village, avec les mêmes produits.","Nina reprend une franchise de restauration rapide sans rien changer à ses recettes ni à son organisation."]},{"id":"creations","type":"tableau","titre":"Créations d’entreprises dans une région imaginée","source":"Chiffres imaginés pour l’exercice, inspirés de l’effet du statut de micro-entrepreneur.","colonnes":["Année","Entreprises créées","Part sans salarié (%)"],"lignes":[[2007,3000,60],[2009,6000,85]],"enteteLignes":true}],"questions":[{"enonce":"Relie chaque auteur à sa définition de l’entrepreneur.","aide":"L’un parle d’innovation, l’autre d’incertitude, la troisième des conditions sociales.","type":"association","gauche":[{"id":"g0","texte":"Schumpeter"},{"id":"g1","texte":"Knight"},{"id":"g2","texte":"La sociologie"}],"droite":[{"id":"d0","texte":"Celui qui assume l’incertitude, un risque non calculable"},{"id":"d1","texte":"Origine sociale, capital et réseau pèsent sur la création"},{"id":"d2","texte":"Celui qui innove et déclenche la destruction créatrice"}]},{"enonce":"Range chaque projet selon qu’il est ou non une innovation au sens de Schumpeter.","aide":"Schumpeter cite un produit, un procédé, un débouché ou une organisation nouveaux.","type":"categories","categories":[{"id":"c0","texte":"Une innovation"},{"id":"c1","texte":"Pas une innovation"}],"items":[{"id":"i0","texte":"La franchise reprise sans rien changer (Nina)"},{"id":"i1","texte":"La boulangerie rouverte à l’identique (Théo)"},{"id":"i2","texte":"Le séchage du bois deux fois plus vite (Sacha)"},{"id":"i3","texte":"La vente de miel dans un pays qui n’en vendait pas (Emma)"}]},{"enonce":"Touche la part d’entreprises sans salarié la plus élevée.","aide":"Lis la dernière colonne.","type":"zone","document":"creations","multiple":false},{"enonce":"En 2009, combien d’entreprises créées n’ont aucun salarié ?","aide":"Applique 85 % à 6 000.","type":"nombre","unite":"entreprises"},{"enonce":"Que montre ce tableau sur l’effet du statut simplifié ?","aide":"Les créations doublent, mais de quelles entreprises s’agit-il ?","type":"choix","options":[{"id":"a","texte":"Une hausse des créations qui a transformé le tissu productif"},{"id":"b","texte":"Un bond des créations, surtout dans les grandes entreprises"},{"id":"c","texte":"Un bond des créations, sans changement profond du tissu productif"},{"id":"d","texte":"Une baisse des créations remplacée par plus de salariés"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**Schumpeter** : l’innovation. **Knight** : l’incertitude. La **sociologie** : l’origine sociale, le capital économique et le réseau jouent sur la probabilité de créer et sur la survie."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Un **procédé** nouveau (Sacha) et un **nouveau débouché** (Emma) sont des innovations. Rouvrir à l’identique ou reprendre sans rien changer n’en est pas une."},{"cle":{"type":"zone","ids":["r1c2"]},"explication":"En 2009, **85 %** des entreprises créées n’ont pas de salarié."},{"cle":{"type":"nombre","valeur":5100,"tolerance":0},"affichage":"5100 entreprises","explication":"85 % de 6 000 = **5 100** entreprises."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les créations **doublent**, mais ce sont des entreprises très petites, souvent sans salarié : le tissu productif change peu."}]$ex$::jsonb),
